mapper.select:
SELECT a.id, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', pm.`id` 'monomer.id', pm.`name` 'monomer.name', pd.`id` 'area.id', pd.`name` 'area.name', ta.serial_number serialNumber, a.number, a.avg_thickness, a.bool_adopt_enum, a.bool_paint_thickness_adopt_enum, su2.name as reporterName, su.name as inspectionName, a.report_time reportTime2 FROM `mes_building_produce_inspection_team_report` a LEFT JOIN tech_artifact ta on ta.id = a.product_id AND ta.bool_delete_enum = FALSE LEFT JOIN contract_project cp ON ta.project_id = cp.id AND cp.bool_delete_enum = FALSE LEFT JOIN plan_monomer pm ON ta.monomer_id = pm.id AND pm.bool_delete_enum = FALSE LEFT JOIN plan_area pd ON ta.area_id = pd.id AND pd.bool_delete_enum = FALSE LEFT JOIN mes_building_produce_team_report c ON c.product_id = a.product_id AND c.number = a.number AND c.task_type_enum = a.task_type_enum AND a.process_id = c.process_id AND c.bool_delete_enum = FALSE LEFT JOIN sys_user su on su.id = a.user_id LEFT JOIN sys_user su2 on su2.id = c.user_id where a.bool_delete_enum = 0 AND a.bool_paint_thickness_adopt_enum is not NULL AND avg_thickness is not null AND a.task_type_enum = 2
AND ta.project_id=#{projectId}
AND a.bool_adopt_enum=#{boolAdoptEnum}
AND a.bool_paint_thickness_adopt_enum=#{boolPaintThicknessAdoptEnum}
AND date(a.create_time) >= date(#{startDate})
AND date(a.create_time) <= date(#{endDate})
AND ta.serial_number like CONCAT('%', #{serialNumber},'%')
AND su.name like CONCAT('%', #{inspectionName},'%')
AND su2.name like CONCAT('%', #{reporterName},'%')
AND a.avg_thickness >= #{minThickness}
AND a.avg_thickness <= #{maxThickness}
AND NOT EXISTS( select 1 from mes_building_produce_inspection_team_report_paint_thickness_link b where b.bool_delete_enum = FALSE and b.inspection_id = a.id and b.thickness < #{minThickness} )
AND NOT EXISTS( select 1 from mes_building_produce_inspection_team_report_paint_thickness_link b where b.bool_delete_enum = FALSE and b.inspection_id = a.id and b.thickness > #{maxThickness} )
order by a.id desc
